<!doctype html><html><head><meta charset="utf-8"><title><?php p($_['batch']['batch_no']);?></title><style>body{font-family:Arial,sans-serif;color:#222;margin:35px;font-size:12px}header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #333;padding-bottom:16px;margin-bottom:24px}h1{font-size:24px;margin:0}h2{font-size:16px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:8px;border-bottom:1px solid #bbb;text-align:left}.num{text-align:right}.hint{margin-top:28px;padding:12px;border:1px solid #999;background:#f5f5f5}.totals{margin-top:20px;text-align:right;font-size:15px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Drucken / als PDF speichern</button><header><div><?php if(!empty($_['logoDataUri'])):?><img src="<?php p($_['logoDataUri']);?>" style="max-width:180px;max-height:80px"><?php endif;?></div><div><h1>Abrechnungsvorbereitung</h1><p><?php p($_['batch']['batch_no']);?><br><?php p(date('d.m.Y',strtotime($_['batch']['created_at'])));?></p></div></header><h2><?php p(($_['customer']['customer_no']??'').' '.($_['customer']['name']??''));?></h2><p>Projekt: <?php p(($_['project']['project_no']??'').' '.($_['project']['title']??''));?></p><table><thead><tr><th>Datum</th><th>Mitarbeiter</th><th>Tätigkeit</th><th class="num">Std.</th><th class="num">Satz</th><th class="num">Arbeitswert</th></tr></thead><tbody><?php foreach($_['items'] as $i):?><tr><td><?php p(date('d.m.Y',strtotime($i['work_date'])));?></td><td><?php p($i['display_name']??$i['user_id']);?></td><td><?php p($i['activity']);?></td><td class="num"><?php p(number_format((float)$i['hours'],2,',','.'));?></td><td class="num"><?php p(number_format((float)$i['hourly_rate'],2,',','.'));?> €</td><td class="num"><?php p(number_format((float)$i['amount'],2,',','.'));?> €</td></tr><?php endforeach;?></tbody></table><div class="totals"><strong><?php p(number_format((float)$_['batch']['total_hours'],2,',','.'));?> Stunden</strong><br>Arbeitswert netto: <strong><?php p(number_format((float)$_['batch']['net_amount'],2,',','.'));?> €</strong></div><div class="hint"><strong>Interne Abrechnungsvorbereitung</strong><br>Dieses Dokument ist keine Rechnung.</div></body></html>
